with parsed as (select id, payload_json, get_json_object(payload_json, '$.user.id') as user_id, cast((status_code & 4) != 0 as int) as flag_bit4, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs) select case when duration_sec >= 3.5 then 'PREMIUM' else 'STANDARD' end as duration_sec_tier, percentile_approx(duration_sec, 0.95) as duration_sec_p95, sum(duration_sec) as total_duration_sec from parsed group by case when duration_sec >= 3.5 then 'PREMIUM' else 'STANDARD' end order by total_duration_sec desc
